import json
from fractions import Fraction as F

# Injective candidates f(x) = a*x + b with a, b exact rationals.
# Check the functional equation exactly on a finite grid of rational x, y.
def satisfies(a, b):
    f = lambda t: a * t + b
    pts = [F(p, q) for p in range(-4, 5) for q in (1, 2, 3)]
    for x in pts:
        for y in pts:
            if f(x) * f(x + y) != f(2 * x + y) - x * f(x + y) + x:
                return False
    return True

def is_injective_linear(a, b):
    return a != 0  # a*x + b is injective on R iff a != 0

coeffs = [F(n, d) for n in range(-3, 4) for d in (1, 2)]
coeffs = sorted(set(coeffs))

solutions_all = []
for a in coeffs:
    for b in coeffs:
        if satisfies(a, b):
            solutions_all.append((a, b))

injective_solutions = [(a, b) for (a, b) in solutions_all if is_injective_linear(a, b)]

# Subquestion: f(0) must equal 1 for any non-zero solution (from x = 0 gives f(y)(f(0)-1) = 0).
f0_checks = [(a, b, b == 1) for (a, b) in injective_solutions]

if len(injective_solutions) == 1:
    a, b = injective_solutions[0]
    final_answer = f"f(x) = {b} + ({a})*x"
else:
    final_answer = "UNSUPPORTED"

evidence = {
    "linear_solutions_found": [[str(a), str(b)] for (a, b) in solutions_all],
    "injective_linear_solutions": [[str(a), str(b)] for (a, b) in injective_solutions],
    "f0_equals_1_for_injective": [bool(c) for (_, _, c) in f0_checks],
    "note": "Search covers linear candidates; x=0 gives f(y)(f(0)-1)=0, so non-zero solutions need f(0)=1.",
}

print(json.dumps({"final_answer": final_answer, "evidence": evidence}))
